const sources = [
  { id: 'hn', name: 'Hacker News (Front Page)', url: 'https://hnrss.org/frontpage' },
  { id: 'techcrunch', name: 'TechCrunch', url: 'https://techcrunch.com/feed/' },
  { id: 'bbc-tech', name: 'BBC Technology', url: 'https://www.thebbc-tech.com/rss/index.xml' },
];
return sources.map((s) => ({ json: s }));

function decodeXml(s) {
  return String(s || '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const out = [];
for (const item of items) {
  const source = item.json;
  // HTTP Request may put body in different shapes
  let xml = '';
  if (typeof item.json === 'string') xml = item.json;
  else if (item.json.data) xml = typeof item.json.data === 'string' ? item.json.data : String(item.json.data);
  else if (item.json.body) xml = String(item.json.body);
  else {
    // paired item: source fields + response
    const keys = Object.keys(item.json);
    for (const k of keys) {
      if (typeof item.json[k] === 'string' && item.json[k].includes('<rss')) {
        xml = item.json[k];
        break;
      }
    }
  }

  // Prefer pairedItem source metadata from previous node via $input
}

// Better: use paired items from List Sources + Fetch RSS via $input.all()
const sourceItems = $('List Sources').all();
const fetchItems = $input.all();
const results = [];

for (let i = 0; i < fetchItems.length; i++) {
  const source = sourceItems[i] ? sourceItems[i].json : { id: 'unknown', name: 'Unknown', url: '' };
  let xml = fetchItems[i].json;
  if (typeof xml !== 'string') {
    if (xml && typeof xml.data === 'string') xml = xml.data;
    else if (xml && typeof xml.body === 'string') xml = xml.body;
    else xml = JSON.stringify(xml);
  }
  if (!xml || !xml.includes('<item')) continue;

  const itemRe = /<item[\s\S]*?<\/item>/gi;
  let match;
  let count = 0;
  while ((match = itemRe.exec(xml)) !== null && count < 8) {
    const block = match[0];
    const title = decodeXml((block.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || '');
    const link = decodeXml((block.match(/<link[^>]*>([\s\S]*?)<\/link>/i) || [])[1] || '');
    const description = decodeXml(
      (block.match(/<description[^>]*>([\s\S]*?)<\/description>/i) || [])[1] || ''
    );
    const pubDate = decodeXml((block.match(/<pubDate[^>]*>([\s\S]*?)<\/pubDate>/i) || [])[1] || '');
    if (!title || !link) continue;
    results.push({
      json: {
        source_id: source.id,
        source_name: source.name,
        title,
        url: link,
        snippet: description.slice(0, 500),
        published_at: pubDate || null,
      },
    });
    count += 1;
  }
}

// Dedupe by URL hostname+path
const seen = new Set();
const unique = [];
for (const row of results) {
  let key;
  try {
    const u = new URL(row.json.url);
    key = (u.hostname + u.pathname).toLowerCase().replace(/\/$/, '');
  } catch {
    key = row.json.title.toLowerCase();
  }
  if (seen.has(key)) continue;
  seen.add(key);
  unique.push(row);
}

// Cap at 8 items, round-robin by source
const bySource = {};
for (const row of unique) {
  const id = row.json.source_id;
  bySource[id] = bySource[id] || [];
  bySource[id].push(row);
}
const selected = [];
const ids = Object.keys(bySource);
let i = 0;
while (selected.length < 8 && ids.some((id) => bySource[id].length)) {
  const id = ids[i % ids.length];
  if (bySource[id].length) selected.push(bySource[id].shift());
  i += 1;
}
return selected;

