const sourceItems = $('Normalize & Dedupe').all();
const aiItems = $input.all();
const out = [];

for (let i = 0; i < aiItems.length; i++) {
  const base = sourceItems[i] ? sourceItems[i].json : {};
  const ai = aiItems[i].json;
  let analysis = null;
  try {
    const text = (ai.candidates && ai.candidates[0] && ai.candidates[0].content && ai.candidates[0].content.parts)
      ? ai.candidates[0].content.parts.map(p => p.text || '').join('')
      : '';
    analysis = JSON.parse(text);
  } catch (e) {
    try {
      const raw = JSON.stringify(ai);
      const m = raw.match(/\{[\s\S]*\}/);
      if (m) analysis = JSON.parse(m[0]);
    } catch (_) {}
  }
  if (!analysis) continue;
  const score = Math.max(1, Math.min(10, Number(analysis.relevance_score) || 5));
  out.push({
    json: {
      title: base.title,
      url: base.url,
      source_id: base.source_id,
      source_name: base.source_name,
      snippet: base.snippet,
      published_at: base.published_at,
      summary: String(analysis.summary || '').trim(),
      category: String(analysis.category || 'Other').trim(),
      key_points: Array.isArray(analysis.key_points) ? analysis.key_points.map(String).slice(0, 5) : [],
      relevance_score: score,
      processed_at: new Date().toISOString(),
    },
  });
}

out.sort((a, b) => b.json.relevance_score - a.json.relevance_score);
return out;

const rows = $input.all().map(i => i.json);
const payload = {
  generated_at: new Date().toISOString(),
  workflow: 'research-content-workflow-demo',
  model: 'gemini-3.5-flash',
  item_count: rows.length,
  items: rows,
};
const jsonText = JSON.stringify(payload, null, 2);

function toCsv(rows) {
  const headers = ['title','url','source_name','category','relevance_score','summary','key_points','published_at','processed_at'];
  const esc = (v) => {
    const s = String(v ?? '');
    if (/[",\n]/.test(s)) return '"' + s.replace(/"/g, '""') + '"';
    return s;
  };
  const lines = [headers.join(',')];
  for (const r of rows) {
    lines.push([
      r.title, r.url, r.source_name, r.category, r.relevance_score, r.summary,
      (r.key_points || []).join(' | '), r.published_at, r.processed_at
    ].map(esc).join(','));
  }
  return lines.join('\n') + '\n';
}

return [
  {
    json: payload,
    binary: {
      research_json: {
        data: Buffer.from(jsonText, 'utf8').toString('base64'),
        mimeType: 'application/json',
        fileName: 'research-results.json',
      },
      research_csv: {
        data: Buffer.from(toCsv(rows), 'utf8').toString('base64'),
        mimeType: 'text/csv',
        fileName: 'research-results.csv',
      },
    },
  },
];
